const label=t=>d.screen.getByLabel(t,{exact:true});const field=t=>d.screen.getByType('TextField').and(label(t));
const log=(name,details={})=>{const row={case:name,status:'PASS',...details};console.log(JSON.stringify(row));fs.appendFileSync(out+'/ios-lifecycle-journal.jsonl',JSON.stringify(row)+'\n');};
async function safe(l,min=180){for(let i=0;i<14;i++){const b=await l.boundingBox(),y=b.y+b.height/2;if(y>=min&&y<=735)return;await d.screen.gesture({pointers:[[{x:200,y:y>735?680:380,time:0},{x:200,y:y>735?380:680,time:500}]]});}throw Error('Unreachable control');}
async function tap(l,min=180){await safe(l,min);await l.tap();}
async function search(q){await field('Search memories').tap();await field('Search memories').fill(q);await d.screen.gesture({pointers:[[{x:200,y:480,time:0},{x:200,y:330,time:500}]]});}
async function state(expected){for(let i=0;i<15;i++){if(read().data.memories.find(m=>m.id===target.id)?.lifecycle===expected)return;await new Promise(r=>setTimeout(r,200));}throw Error('Lifecycle did not become '+expected);}
async function recovery(){await label('CasitaDex logo, go to Home').tap();await label('Settings').tap();await tap(label('Recently deleted'));await label('View recently deleted memories').waitFor({state:'visible',timeout:8000});}
